 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.shrsTable_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_listShrsList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_listShrsList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.deleteRow === 'function') { scwin.deleteRow("this"); } else { console.error('[sdd] 행 동작 미정의: scwin.deleteRow (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.deleteRow'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'shrsTable.oncellclick' });
    }
};

