/**
 * @method
 * @name scwin.tx_fn_regist
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_regist = async function () {
    const sbmOptions = {
        id: "tx_fn_regist",
        method: "post",
        action: "/listInvstg/listShrs.do",
        ref: "dma_registReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil55200n.tx_fn_regist" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_update
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
