/**
 * @method
 * @name scwin.specialWord
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.specialWord = async function () {
    /* sdd-asis-lifecycle:begin fn_specialWord — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let nm = dma_hiddenStore.get("nm");
    if (nm.indexOf("\\") !== -1) {
        nm = nm.replace(/\\/g, "");
        ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('nm', nm) : console.warn('[sdd] hiddenStore 부재: nm'));
        await $c.win.alert("\\는 입력할 수 없습니다");
    }
    if (nm.indexOf("\"") !== -1) {
        nm = nm.replace(/"/g, "");
	($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('nm', nm) : console.warn('[sdd] hiddenStore 부재: nm'));
	await $c.win.alert("\"는 입력할 수 없습니다");
    }
    /* sdd-asis-lifecycle:end */
};
